					danceData.DecLiveScore(checkStackHeartNum);
					applyScoreResult.pattern = EmitHeartPattern.Large;
					totalScore += checkStackHeartNum;
				}

				applyScoreResult.gaugeRatio = CalcTotalRatio();
				result = applyScoreResult;
				return true;
			}

			result = null;
			return false;
		}
