		public void LaunchSkill(double elapsedTime, int playerIndex, bool isPrevSameWazaType) {
			chainCount++;
			lastUsePlayerIndex = playerIndex;
			launchSkillElapsedTime = elapsedTime;
			CheckUntilUseSkillPlayer();
			PlayLaunchWazaSE(playerIndex, isPrevSameWazaType);

			PlayerDanceDataModel danceData = playerDataArray[playerIndex];
			comboBonusDataArray[playerIndex].IsContain = true;
			if (comboBonus.CanGetChainBonus(chainCount))
			{
				int bonus = comboBonus.CalcComboBonus(chainCount, danceData.contestSkill.WazaType);
				for (int i = 0; i < comboBonusDataArray.Length; i++)
					comboBonusDataArray[i].score += bonus;
			}
			else
			{
				comboBonus.SetWazaType(danceData.contestSkill.WazaType);
			}
		}
		private void CheckUntilUseSkillPlayer() {
			for (int i = 0; i < playerDataArray.Length; i++)
			{
				if (!playerDataArray[i].IsAlreadyUseSkill)
				{
					canUpdateChain = true;
					return;
				}
			}

			canUpdateChain = false;
		}
		public void OnLockPlayerContestSkill() {
			for (int i = 0; i < playerDataArray.Length; i++)
			{
				if (!playerDataArray[i].IsAlreadyUseSkill)
					return;
			}

			canUpdateChain = false;
		}
		private void PlayLaunchWazaSE(int playerIndex, bool isPrevSameWazaType) {
			if (isPrevSameWazaType)
				ContestSoundPlayer.player.PlaySeByID(ContestSoundPlayer.PlaySE_ID.Waza_SameType);
			else if (playerIndex < 2)
				ContestSoundPlayer.player.PlaySeByID(ContestSoundPlayer.PlaySE_ID.Waza_L);
			else
				ContestSoundPlayer.player.PlaySeByID(ContestSoundPlayer.PlaySE_ID.Waza_R);
		}
		public float CalcChaniGaugeRatio(double elapsedTime) {
			float ratio = (float)(elapsedTime - launchSkillElapsedTime) / skillChainDuration;
			if (ratio > 1.0f)
			{
				ratio = 1.0f;
				canUpdateChain = false;
				chainCount = 0;
			}

			return ratio;
		}
		public global::Dpr.Contest.PlayerDanceDataModel CalcPlayerScoreAfterContestWaza(global::Dpr.Contest.PlayerDanceDataModel danceDataModel, double startElapsedTime, double endElapsedTime, bool isUser) {
			PlayerDanceDataModel calcDataModel = new PlayerDanceDataModel();
			calcDataModel.SetPlayerData(danceDataModel);
			lastNoteData = null;

			int noteIndex = calcDataModel.currentNoteDataIndex;
			for (; noteIndex < currentNoteDataList.Count; noteIndex++)
			{
				NotesDataModel noteData = currentNoteDataList[noteIndex];
				if (noteData.arriveSec < startElapsedTime)
					continue;

				if (noteData.arriveSec > endElapsedTime)
					break;

				lastNoteData = noteData;
				if (isUser && IsLongTap && lastNoteData.index == longStartNote.NoteData.index)
					continue;

				lastNoteData.emitFlag = !isUser;
				switch (lastNoteData.notesType)
				{
					case NoteTypeID.Normal:
					case NoteTypeID.LongStart:
						UpdatePlayerDataByTimingID(calcDataModel, NoteTapTimingID.Best);
						break;
					case NoteTypeID.LongEnd:
						UpdateHeartGauge(calcDataModel, NoteTapTimingID.Best);
						UpdatePlayerDataByTimingID(calcDataModel, NoteTapTimingID.Best);
						break;
				}
			}

			if (lastNoteData == null)
				return calcDataModel;

			if (lastNoteData.notesType == NoteTypeID.LongStart)
			{
				lastNoteData = currentNoteDataList[noteIndex];
				lastNoteData.emitFlag = !isUser;
				UpdateHeartGauge(calcDataModel, NoteTapTimingID.Best);
				UpdatePlayerDataByTimingID(calcDataModel, NoteTapTimingID.Best);
				noteIndex++;
			}

			calcDataModel.currentNoteDataIndex = noteIndex;
			danceDataModel.currentNoteDataIndex = noteIndex;
			return calcDataModel;
		}
		public void ApplyScoreBonus() {
			for (int i = 0; i < comboBonusDataArray.Length; i++)
			{
				PlayerDanceDataModel danceData = playerDataArray[i];
				if (comboBonusDataArray[i].IsContain)
					danceData.AddWazaScore(comboBonusDataArray[i].score);

				comboBonusDataArray[i].Reset();
			}

			comboBonus.ResetWazaType();
			lastUsePlayerIndex = -1;
		}
		public bool CheckSamePrevWazaType() {
			return comboBonus.PrevWazaType == userDataModel.contestSkill.WazaType;
		}
		public bool CheckSameUserWazaType(int palyerIndex) {
